base.r/main.tf:
terraform {
  backend "s3" {}
}
data "dns_a_record_set" "x" {
  host = "example.com"
}
locals {
  suffix = "/32"
}
resource "aws_security_group_rule" "r" {
  type              = "ingress"
  security_group_id = "sg-1"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [for ip in data.dns_a_record_set.x.addrs : "${ip}${local.suffix}"]
}

