base.r/main.tf:
terraform {
  backend "s3" {}
}
variable "cidr" {
  default = "10.0.0.0/8"
}
data "aws_ssm_parameter" "flag" {
  name = "f"
}
resource "aws_ssm_parameter" "p" {
  name  = "p"
  type  = "String"
  value = "%{ if data.aws_ssm_parameter.flag.value }${var.cidr}%{ else }10.0.0.0/8%{ endif }"
}

